using Godot;
using System;
using System.Linq;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
 HFlowContainer knownTargetBar=null!;OptionButton knownTargetChoice=null!;Label knownTargetInfo=null!;EntityId[] knownTargetIds=[];string? selectedKnownTarget;
 static string KnownTargetName(MilitaryKnownUnit row)=>row.Kind=="own"?Array.IndexOf(NewGameMilitary.UnitIds,row.Unit) switch{0=>"本隊",1=>"左分隊",2=>"右分隊",_=>"確認した部隊"}:"演習相手";
 void BuildKnownTargetUI(VBoxContainer root){knownTargetBar=new();root.AddChild(knownTargetBar);knownTargetBar.AddChild(new Label{Text="確認した部隊"});knownTargetChoice=new(){CustomMinimumSize=new(200,0)};knownTargetBar.AddChild(knownTargetChoice);knownTargetChoice.ItemSelected+=index=>{selectedKnownTarget=knownTargetIds[(int)index].Value;Refresh();};Add(knownTargetBar,"known-target-go","記録の場所へ本人が向かう",GoKnownTarget);Add(knownTargetBar,"known-target-query","選択した隊へ照会",QueryKnownTarget);knownTargetInfo=new(){AutowrapMode=TextServer.AutowrapMode.WordSmart,SizeFlagsHorizontal=SizeFlags.ExpandFill,CustomMinimumSize=new(360,0)};knownTargetBar.AddChild(knownTargetInfo);BuildUnitDirectiveUI(root);}
 bool KnownTargetAllowed(ContractWorld w,MilitaryKnownUnit? row)=>row!=null&&NewGameMilitary.WithdrawalAllowed(w,new(new("request:known-availability"),NewMilitaryAction.PersonalMove,0,row.Position))&&RegionalGround.Distance(NewGameMilitary.Anchor(w),row.Position)<=120000;
 void RefreshKnownTarget(){if(knownTargetBar==null)return;var w=Snapshot();var rows=RecognizedUnits(w);knownTargetBar.Visible=NewGameMilitary.RecognitionEnabled(w);var ids=rows.Select(r=>r.Unit).ToArray();if(!ids.SequenceEqual(knownTargetIds)){knownTargetChoice.Clear();knownTargetIds=ids;foreach(var row in rows)knownTargetChoice.AddItem(KnownTargetName(row));}if(selectedKnownTarget==null||!ids.Any(id=>id.Value==selectedKnownTarget))selectedKnownTarget=ids.FirstOrDefault().Value;int index=Array.FindIndex(ids,id=>id.Value==selectedKnownTarget);if(index>=0)knownTargetChoice.Select(index);for(int i=0;i<rows.Length;i++)knownTargetChoice.SetItemText(i,KnownTargetName(rows[i])+(rows[i].Live?"（現地）":"（過去情報）"));var chosen=index>=0?rows[index]:null;buttons["known-target-go"].Disabled=!KnownTargetAllowed(w,chosen);buttons["known-target-query"].Disabled=chosen?.Kind!="own"||!NewGameMilitary.UnitInquiryAllowed(w,NewMilitaryAction.InquireUnitKnown);knownTargetInfo.Text=chosen==null?"確認した部隊の記録はありません":KnownTargetName(chosen)+" / "+chosen.Source+"・開始"+chosen.ObservedAt+"秒 / "+chosen.Soldiers+"人";var intent=w.NewMilitary?.Requests.LastOrDefault(q=>q.Input.Action==NewMilitaryAction.PersonalMove)?.Input.KnownTarget;if(intent!=null)knownTargetInfo.Text+=" / 今回の行先は開始"+intent.ObservedAt+"秒の記録位置";if(chosen!=null&&!NewGameMilitary.Detached(w))knownTargetInfo.Text+=" / 本人だけで移動するには部隊と別行動にします";RefreshUnitDirective();}
 void GoKnownTarget(){var w=Snapshot();if(selectedKnownTarget==null)return;var target=NewGameMilitary.SelectKnownTarget(w,new(selectedKnownTarget));if(target==null){message.Text="現在の認識にない対象です。";Refresh();return;}Submit(Session.DecideNewMilitary(new NewMilitaryInput(new("request:known-destination-ui/"+Session.Revision),NewMilitaryAction.PersonalMove,0,target.Position){KnownTarget=target},Session.PlayerControl,Session.Revision));}
 void QueryKnownTarget(){var w=Snapshot();if(selectedKnownTarget==null)return;var target=NewGameMilitary.SelectKnownTarget(w,new(selectedKnownTarget));if(target==null)return;Submit(Session.DecideNewMilitary(new NewMilitaryInput(new("request:selected-unit-query/"+Session.Revision),NewMilitaryAction.InquireUnitKnown){InquiryTarget=new(NewGameMilitary.UnitRecipientContract,target),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},Session.PlayerControl,Session.Revision));}
 SavePresentation CurrentPresentation()=>new(fraction,speed,null,new(0,0,Span,Yaw,!nationMode,true),MilitaryTarget:selectedKnownTarget,MilitaryOriginal:selectedDirectiveOriginal,MilitaryCancellation:selectedCancellationOriginal);
 object? KnownTargetPose()=>knownTargetBar==null?null:new{Selected=selectedKnownTarget,Choices=knownTargetIds,knownTargetBar.Visible,Text=knownTargetInfo.Text,GoEnabled=!buttons["known-target-go"].Disabled,QueryEnabled=!buttons["known-target-query"].Disabled,Directive=UnitDirectivePose()};
 internal void SelectKnownMilitary(EntityId unit){Refresh();int index=Array.IndexOf(knownTargetIds,unit);if(index<0)throw new InvalidOperationException("Unknown target cannot be selected");knownTargetChoice.Select(index);knownTargetChoice.EmitSignal(OptionButton.SignalName.ItemSelected,index);}
}
